INSERT INTO repositories (id, owner_id, slug, title, description, category, industry, visibility, created_at) VALUES
('22222222-2222-2222-2222-222222222221', '11111111-1111-1111-1111-111111111111', 'acmefood-unit-economics', 'AcmeFood: the unit economics investigation', 'A fictional delivery startup case study documenting how growth concealed an unsustainable service model.', 'Startup', 'Food technology', 'PUBLIC', CURRENT_TIMESTAMP),
('22222222-2222-2222-2222-222222222222', '11111111-1111-1111-1111-111111111111', 'cloudbox-migration-review', 'CloudBox migration review', 'A fictional engineering incident archive about a high-risk database migration.', 'Engineering', 'Cloud software', 'PUBLIC', CURRENT_TIMESTAMP),
('22222222-2222-2222-2222-222222222223', '11111111-1111-1111-1111-111111111111', 'campusloop-marketplace-notes', 'CampusLoop marketplace notes', 'A fictional campus marketplace research repository.', 'Product', 'Education technology', 'PUBLIC', CURRENT_TIMESTAMP);
INSERT INTO failures (id, repository_id, author_id, title, summary, root_cause, warning_signs, lessons_learned, prevention, severity, status, tags, occurred_year, created_at, updated_at) VALUES
('33333333-3333-3333-3333-333333333331', '22222222-2222-2222-2222-222222222221', '11111111-1111-1111-1111-111111111111', 'Paid growth hid negative unit economics', 'AcmeFood increased order volume quickly, but every subsidized order deepened the cash deficit. The team did not have a retention threshold before scaling acquisition.', 'Contribution margin remained negative after incentives, delivery costs, and refunds were included.', 'Repeat order rate flattened while paid acquisition spend rose for three consecutive months.', 'Do not scale paid acquisition before retention and contribution margin meet predefined thresholds.', 'Run cohort contribution analysis monthly and cap acquisition spend until repeat behaviour is proven.', 9, 'PUBLISHED', 'unit economics, retention, CAC, marketplace', 2025, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('33333333-3333-3333-3333-333333333332', '22222222-2222-2222-2222-222222222222', '11111111-1111-1111-1111-111111111111', 'Migration rollback exceeded the recovery window', 'CloudBox migrated a customer data workload during peak traffic. A rollback was designed but had never been rehearsed against production-sized data.', 'The migration plan treated rollback as a configuration switch instead of a data recovery operation.', 'Replica lag rose in rehearsal, but the launch gate had no explicit lag limit.', 'A rollback plan is only credible after it succeeds under representative load and data volume.', 'Require a measured recovery objective, a rehearsed rollback, and a traffic freeze before irreversible migrations.', 8, 'PUBLISHED', 'database migration, rollback, operations, reliability', 2026, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('33333333-3333-3333-3333-333333333333', '22222222-2222-2222-2222-222222222223', '11111111-1111-1111-1111-111111111111', 'Campus marketplace stalled at the cold start', 'CampusLoop opened across too many campuses before proving enough local supply and demand in one community.', 'The launch strategy optimized geographic reach rather than dense local liquidity.', 'New users saw empty listings and sellers received few enquiries in the first week.', 'Marketplaces need a narrow, measurable liquidity loop before expanding geography.', 'Launch one category in one campus, recruit supply first, and set a minimum successful-match rate before expansion.', 7, 'PUBLISHED', 'marketplace, cold start, liquidity, product market fit', 2025, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('33333333-3333-3333-3333-333333333334', '22222222-2222-2222-2222-222222222222', '11111111-1111-1111-1111-111111111111', 'Alert fatigue delayed the incident response', 'A noisy alert channel trained the on-call team to ignore repeated warnings until customer impact became visible.', 'Alert rules were not owned, deduplicated, or tied to an actionable runbook.', 'The same low-priority alert appeared hundreds of times before the outage.', 'An alert without an owner and a response action is operational noise, not observability.', 'Review alert volume weekly, remove non-actionable signals, and attach a runbook to every paging rule.', 6, 'PUBLISHED', 'alerting, incident response, observability, operations', 2026, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
